UPDATE TB_DRCTL01
   SET STATUS_CD = #{statusCd}
      ,CS_ACK_DT = #{csAckDt}
      ,REASON_CD = #{reasonCd}
      ,UPD_DT    = NOW()
      ,UPD_ID    = #{updUserId}
 WHERE CONTROL_ID = #{controlId} AND ORIGIN_CD = #{originCd}

UPDATE TB_DRCTL01
   SET STATUS_CD = #{newStatus}
      ,UPD_DT    = NOW()
      ,UPD_ID    = #{updUserId}
 WHERE CP_ID = #{cpId}
   AND CS_ID = #{csId}
   AND CONTROL_TYPE = #{controlType}
   AND IS_DEFAULT = #{isDefault}
   AND ORIGIN_CD = #{originCd}
   AND STATUS_CD IN ('ACTIVE','PENDING')

